SELECT RECORD_ID as "recordId", VOUCHER_ID as "voucherId", VOUCHER_NO as "voucherNo", VOUCHER_TYPE as "voucherType", TOTAL_AMOUNT as "totalAmount", POSTING_TIME as "postingTime", POSTING_BY as "postingBy", POSTING_BY_NAME as "postingByName", UNPOST_REASON as "unpostReason", UNPOST_TIME as "unpostTime", UNPOST_BY as "unpostBy", UNPOST_BY_NAME as "unpostByName", UNPOST_STATUS as "unpostStatus", REPOST_TIME as "repostTime", REPOST_BY as "repostBy", REPOST_BY_NAME as "repostByName", BOOK_ID as "bookId", TENANT_ID as "tenantId", REMARK as "remark", CREATE_TIME as "createTime" FROM TBL_VOUCHER_UNPOST_RECORD WHERE IS_DELETED = 0
AND VOUCHER_NO LIKE '%' || #{param.voucherNo} || '%'
AND VOUCHER_TYPE = #{param.voucherType}
AND UNPOST_STATUS = #{param.unpostStatus}
AND UNPOST_TIME >= TO_TIMESTAMP(#{param.startDate}, 'YYYY-MM-DD HH24:MI:SS')
AND UNPOST_TIME <= TO_TIMESTAMP(#{param.endDate}, 'YYYY-MM-DD HH24:MI:SS')
AND BOOK_ID = #{param.bookId}
AND TENANT_ID = #{param.tenantId}
ORDER BY UNPOST_TIME DESC

SELECT COUNT(1)
FROM TBL_VOUCHER_UNPOST_RECORD
WHERE IS_DELETED = 0

    AND VOUCHER_NO LIKE '%' || #{param.voucherNo} || '%'


    AND VOUCHER_TYPE = #{param.voucherType}


    AND UNPOST_STATUS = #{param.unpostStatus}


    AND UNPOST_TIME >= TO_TIMESTAMP(#{param.startDate}, 'YYYY-MM-DD HH24:MI:SS')


    AND UNPOST_TIME <= TO_TIMESTAMP(#{param.endDate}, 'YYYY-MM-DD HH24:MI:SS')


    AND BOOK_ID = #{param.bookId}


    AND TENANT_ID = #{param.tenantId}
